export type Cell = [number, number];

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const key = (x: number, y: number): string => `${x},${y}`;
  const live = new Set(liveCells.map(([x, y]) => key(x, y)));

  const neighbourCounts = new Map<string, number>();
  for (const [x, y] of liveCells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        const neighbour = key(x + dx, y + dy);
        neighbourCounts.set(neighbour, (neighbourCounts.get(neighbour) ?? 0) + 1);
      }
    }
  }

  const survivors: Cell[] = [];
  for (const [cellKey, count] of neighbourCounts) {
    const isAlive = live.has(cellKey);
    if (count === 3 || (count === 2 && isAlive)) {
      const [x, y] = cellKey.split(",").map(Number);
      survivors.push([x, y]);
    }
  }

  return survivors;
}

